refentry.refsect1:
  &reftitle.parameters;


    value


generator भित्र पठाइने Value। यो value, generator हाल रहेको &yield; expression को return value हुनेछ।

  &reftitle.examples;



    values inject गर्नका लागि Generator::send को प्रयोग


<?php
function printer() {
    echo "I'm printer!".PHP_EOL;
    while (true) {
        $string = yield;
        echo $string.PHP_EOL;
    }
}

$printer = printer();
$printer->send('Hello world!');
$printer->send('Bye world!');
?>


    &example.outputs;


I'm printer!
Hello world!
Bye world!
